(function(){
  const wrap=document.getElementById('fx-zoom-wrap');if(!wrap)return;
  const r=wrap.getBoundingClientRect();
  const x0=r.left+r.width*0.3,y0=r.top+r.height*0.3,x1=r.left+r.width*0.6,y1=r.top+r.height*0.6;
  wrap.dispatchEvent(new PointerEvent('pointerdown',{clientX:x0,clientY:y0,bubbles:true}));
  wrap.dispatchEvent(new PointerEvent('pointermove',{clientX:x1,clientY:y1,bubbles:true}));
})()

